"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";
import { focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const Tabs = TabsPrimitive.Root;

/**
 * Ink mail TabsList: a tray of segmented chips. The tray is the elevated
 * surface step behind a hairline, with a 0.75rem corner and 0.25rem inset.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex items-center gap-1 rounded-lg border border-border bg-secondary p-1 text-muted-foreground",
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Ink mail TabsTrigger: a 2rem chip in muted ink that brightens on hover.
 * The active chip takes the white wash and full off-white ink.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "inline-flex h-8 shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md px-3",
      "text-sm font-medium text-muted-foreground",
      "transition-colors duration-fast ease-out hover:text-foreground",
      "data-[active]:bg-(--wash) data-[active]:text-foreground",
      focusRing,
      "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Ink mail TabsContent: the active panel, set a little below the tray. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn("mt-4 rounded-md", focusRing, className)}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
